local function Completed(step)
    if step.ZoneStepTrigger or not C_QuestLog or not C_QuestLog.IsQuestFlaggedCompleted then return false end
    if C_QuestLog.IsQuestFlaggedCompleted(step.Waypoint) then return true end
    for _, id in ipairs(step.WaypointDB or {}) do
        if C_QuestLog.IsQuestFlaggedCompleted(id) then return true end
    end
    return false
