function Integration:GetText(step, point, token)
    local title = point and (point.label or point.instruction)
    if not title or title == "" then
        if not self.summary or self.summary.token ~= token then
            self.summary = { token = token, text = APR:CheckWaypointText() }
        end
        title = self.summary.text
    end
    local lines, seen, keys = {}, {}, {}
    local function Add(raw)
        for _, line in ipairs(APR:ResolveStepTextList(raw)) do
            if line.text ~= title and not seen[line.text] then
                seen[line.text], lines[#lines + 1] = true, line.text
            end
        end
    end--[[APR_DIAG]]; Add = APRTrace("APR-Core/integrations/Waypoint.lua:59:Add#10", Add)--[[/APR_DIAG]]
    -- Hints belong to the actual authored step, even while travelling towards it.
    Add(step.Note)
    for key in pairs(step) do
        if type(key) == "string" and key:match("^ExtraLineText%d*$") then keys[#keys + 1] = key end
    end
    table.sort(keys)
    for _, key in ipairs(keys) do Add(step[key]) end
    return title or "APR", #lines > 0 and table.concat(lines, "\n") or nil
end--[[APR_DIAG]]; Integration.GetText = APRTrace("APR-Core/integrations/Waypoint.lua:50:Integration:GetText#9", Integration.GetText)--[[/APR_DIAG]]

function Integration:GetTarget()
    if self.stopped or not Enabled() or APR.stepUpdateRunning or APR.stepUpdatePending then return nil end
    if self.cancelledContext and APR:IsStepContextCurrent(self.cancelledContext) then return nil end
    local preview = APR.navigationPreview
    if not preview then return nil end
    local step, index = APR:GetCurrentStep()
    if not step then return nil end
    local nav, point, transient = APR.navigation
    if nav and nav.retainedArrow then
        point, transient = nav:GetRetainedArrow(), true
    elseif nav and nav:IsNavigating() then
        if nav.context and not APR:IsStepContextCurrent(nav.context) then return nil end
        point, transient = nav:GetActiveStep(), true
    elseif nav and nav.state ~= "ready" then
        return nil
    end
    if transient then
        if not point or point.displayAction or (point.sourceFree and point.action) then return nil end
    else
        if not step.Waypoint or step.NoArrow or not APR.IsInRouteZone or Completed(step) then return nil end
        local _, routeMap = APR:GetCurrentRouteMapIDsAndName()
        local hint = APR:GetPlayerParentMapID()
        local coord, zone = APR:GetStepCoord(step, routeMap, hint)
        local mapID = zone or (APR.GetStepZoneForPlayer and APR:GetStepZoneForPlayer(step, routeMap, hint))
            or (type(step.Zone) == "number" and step.Zone) or routeMap
        point = preview:Point({ Coord = coord, uiMapID = mapID,
            instanceID = step.instanceID })
    end
    if not point or not point.Coord then return nil end
    local coord = point.Coord
    if not Finite(coord.x) or not Finite(coord.y) then return nil end
    local mapID = coord.mapID or point.uiMapID
    if not Finite(mapID) or mapID <= 0 then return nil end
    local instanceID = point.instanceID or coord.instanceID or preview:GetMapInstance(mapID)
    local playerY, playerX, _, playerInstance = UnitPosition("player")
    if not Finite(playerInstance) or (instanceID ~= nil and instanceID ~= playerInstance) then return nil end
    local x, y = preview:ProjectPoint(point, mapID)
    if not Finite(x) or not Finite(y) or x < 0 or x > 1 or y < 0 or y > 1 then return nil end
    local context = APR:CaptureStepContext()
    local token = table.concat({ tostring(context.player), tostring(context.route), tostring(index),
        tostring(context.revision), tostring(context.definition), tostring(step),
        transient and tostring(point.id or point) or "step", tostring(instanceID), tostring(mapID), tostring(x), tostring(y) }, "\031")
    if self.arrivedToken == token then return nil end
    -- Arrival only retires this presentation. Arrow/route handlers own all progress.
    if not transient and Finite(step.Range) and step.Range > 0 and Finite(playerX) and Finite(playerY) then
        local playerMap = C_Map.GetBestMapForUnit("player")
        local projected = preview:ProjectPoint(point, playerMap)
        if projected and (coord.x - playerX)^2 + (coord.y - playerY)^2 < step.Range^2 then
            self.arrivedToken = token
            return nil
        end
    end
    local title, subtext = self:GetText(step, transient and point or nil, token)
    return { mapID = mapID, x = x, y = y, title = title, subtext = subtext, token = token,
        point = point, transient = transient, source = "apr.step#" .. tostring(index) .. (transient and ":" .. tostring(point.id or "navigation") or ""),
        kind = "guide_goal", guideProvider = "apr" }
end--[[APR_DIAG]]; Integration.GetTarget = APRTrace("APR-Core/integrations/Waypoint.lua:76:Integration:GetTarget#11", Integration.GetTarget)--[[/APR_DIAG]]

