function Integration:Refresh()
    if self.writing then return end
    local enabled = Enabled() and not self.stopped
    if enabled and self.wasEnabled == false then
        self.cancelledContext, self.dismissedToken, self.arrivedToken = nil, nil, nil
    end
    self.wasEnabled = not not enabled
    if not enabled then self:Release(); return end
    if self.pendingRelease then self:ReleaseWaypointUI() end
    local aw = self:ConnectAzerothWaypoint()
    local api = WaypointUI()
    if not aw and not api then return end
    local target = self:GetTarget()
    self.lastTarget = target
    if aw then
        self:ReleaseWaypointUI()
        if InCombat() then return end
        if self.pendingAWRelease then self.awNS.ClearGuideRouteState("apr"); self.pendingAWRelease, self.awActive = nil, nil end
        local signature = target and target.token .. target.title .. (target.subtext or "") or "none"
        if signature ~= self.awSignature then
            self.awSignature = signature
            -- AWP keeps its existing provider selection, manual authority, routing and TomTom carrier.
            self.awNS.ScheduleGuideProviderEvaluation("apr", "APRGuidance")
            self.awActive = true
        end
    else
        self:RefreshWaypointUI(api, target)
    end
end--[[APR_DIAG]]; Integration.Refresh = APRTrace("APR-Core/integrations/Waypoint.lua:265:Integration:Refresh#19", Integration.Refresh)--[[/APR_DIAG]]

