        "ZONE_CHANGED_INDOORS", "USER_WAYPOINT_UPDATED", "SUPER_TRACKING_CHANGED", "SUPER_TRACKING_PATH_UPDATED",
        "PLAYER_REGEN_ENABLED", "PLAYER_DEAD", "PLAYER_ALIVE", "PLAYER_UNGHOST" }) do
